return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Urdu','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 20:21+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'ur','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'لینگوا فورج','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'ملٹی لسانی راستہ بندی، SEO میٹا ٹیگز، اور AI مواد کے اوزار ورڈپریس کے لیے۔ زبان کا پتہ لگانے، URL راستہ بندی، hreflang، میٹا تفصیلات، اور AI سے چلنے والی اقتباس، میٹا، اور ترجمہ کی خصوصیات کو یکجا کرتا ہے۔','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'ترجمہ کریں','Lingua Forge — Quick Translate'=>'لینگوا فورج — فوری ترجمہ','Informative'=>'معلوماتی','Persuasive'=>'قائل','Storytelling'=>'کہانی سنانا','Technical'=>'تکنیکی','Conversational'=>'بات چیت','Permission denied.'=>'اجازت نامہ مسترد۔','Cannot determine target language from slug.'=>'ہدف زبان slug سے معلوم نہیں ہو سکی۔','Invalid post type.'=>'غلط پوسٹ قسم۔','Invalid or primary language.'=>'غلط یا بنیادی زبان۔','Template not found or not stored in the database.'=>'سانچہ نہیں ملا یا ڈیٹا بیس میں محفوظ نہیں۔','Template has no content.'=>'سانچہ کا مواد نہیں ہے۔','No internal links found to update.'=>'اپ ڈیٹ کرنے کے لیے کوئی داخلی روابط نہیں ملے۔','%d link updated.'=>'%d لنک اپ ڈیٹ کیا گیا۔' . "\0" . '%d لنکس اپ ڈیٹ کیے گئے۔','No language-specific template parts found to map.'=>'زبان سے مخصوص سانچہ کے حصے نہیں ملے۔','No template part references needed updating.'=>'سانچہ کے حصے کے حوالے کی ضرورت نہیں۔','%d part reference updated.'=>'%d حصے کا حوالہ اپ ڈیٹ کیا گیا۔' . "\0" . '%d حصوں کے حوالے اپ ڈیٹ کیے گئے۔','Invalid language.'=>'غلط زبان۔','Template part not found or not stored in the database.'=>'سانچہ کا حصہ نہیں ملا یا ڈیٹا بیس میں محفوظ نہیں۔','Template part has no content.'=>'سانچہ کا حصہ کا مواد نہیں ہے۔','No navigation references needed updating.'=>'نیویگیشن کے حوالے کی ضرورت نہیں۔','%d navigation reference updated.'=>'%d نیویگیشن حوالہ اپ ڈیٹ کیا گیا۔' . "\0" . '%d نیویگیشن حوالہ جات اپ ڈیٹ کیے گئے۔','No AI provider configured.'=>'AI فراہم کنندہ ترتیب نہیں دیا گیا۔','Missing pattern name or language.'=>'پٹرن کا نام یا زبان غائب ہے۔','Pattern not found.'=>'پٹرن نہیں ملا۔','Pattern has no content to translate.'=>'پٹرن کا مواد ترجمہ کے لیے نہیں ہے۔','AI provider returned an empty response.'=>'AI فراہم کنندہ نے خالی جواب دیا۔','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'پٹرن ترجمہ کیا گیا اور محفوظ کیا گیا۔ مواد کو اپنے CPT پوسٹ میں کاپی کریں یا اسے ری یوز ایبل بلاک کے لیے شروع کرنے کے طور پر استعمال کریں۔','Invalid template type.'=>'غلط سانچہ قسم۔','Template "%s" already exists.'=>'سانچہ "%s" پہلے سے موجود ہے۔','"%s" created.'=>'"%s" تخلیق کیا گیا۔','Invalid template part.'=>'غلط سانچہ حصہ۔','Template part "%s" already exists.'=>'سانچہ حصہ "%s" پہلے سے موجود ہے۔','"%1$s" created. %2$d template updated.'=>'"%1$s" تخلیق کیا گیا۔ %2$d سانچے اپ ڈیٹ کیے گئے۔' . "\0" . '"%1$s" تخلیق کیا گیا۔ %2$d سانچے اپ ڈیٹ کیے گئے۔','Page'=>'صفحہ','Single'=>'سنگل','Search'=>'تلاش','Search Results'=>'تلاش کے نتائج','Archive'=>'آرکائیو','Front Page'=>'فرنٹ پیج','Single: %s'=>'سنگل: %s','Single %s'=>'سنگل %s','Archive: %s'=>'آرکائیو: %s','%s Archive'=>'%s آرکائیو','No source content found to translate.'=>'کوئی ماخذ مواد ترجمہ کے لیے نہیں ملا۔','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'ترجمہ کیا گیا۔ سائٹ ایڈیٹر میں جائزہ لیں — اندرونی روابط، نیویگیشن یو آر ایل، اور ٹیمپلیٹ سلگ خودکار طور پر اپ ڈیٹ نہیں ہوتے۔','Navigation not found.'=>'نیویگیشن نہیں ملی۔','Navigation has no content to translate.'=>'نیویگیشن کا کوئی مواد ترجمہ کے لیے موجود نہیں۔','"%1$s %2$s" saved.'=>'"%1$s %2$s" محفوظ کیا گیا۔','Translate page…'=>'صفحہ ترجمہ کریں…','Generate content…'=>'مواد تیار کریں…','AI Behaviour Preset'=>'AI رویہ پری سیٹ','Custom'=>'حسبِ ضرورت','Global default (%s)'=>'عالمی ڈیفالٹ (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'اس صفحہ پر ترجمہ اور مواد کی تخلیق کے لیے AI پری سیٹ کو اووررائیڈ کرتا ہے۔ سائٹ بھر میں حسبِ ضرورت پرامپٹ ہدایات (سیٹنگز → رویہ) ہر درخواست کے ساتھ شامل کی جاتی ہیں، چاہے اس انتخاب سے کوئی فرق نہ پڑے۔','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'اس صفحہ پر ترجمہ اور مواد کی تخلیق کے لیے AI پری سیٹ کو اووررائیڈ کرتا ہے۔ دیگر تمام خصوصیات ہمیشہ عالمی پری سیٹ استعمال کرتی ہیں۔','Close'=>'بند کریں','Translate missing'=>'غائب ترجمہ کریں','From'=>'سے','Retranslate'=>'دوبارہ ترجمہ کریں','Translating…'=>'ترجمہ ہو رہا ہے…','Retranslating…'=>'دوبارہ ترجمہ ہو رہا ہے…','✓ Done'=>'✓ مکمل','Error'=>'خرابی','Navigation posts are translated via the Router tab, not this button.'=>'نیویگیشن پوسٹس راؤٹر ٹیب کے ذریعے ترجمہ کی جاتی ہیں، اس بٹن کے ذریعے نہیں۔','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'پوسٹ قسم "%s" کے لیے ترجمہ تخلیق کرنے کے لیے ایک فعال انٹیگریشن درکار ہے۔ براہ کرم یقینی بنائیں کہ مطلوبہ انٹیگریشن انسٹال اور فعال ہے۔','No %s version found in this translation group.'=>'اس ترجمہ گروپ میں کوئی %s ورژن نہیں ملا۔','AI Usage'=>'AI استعمال','Today'=>'آج','Last 7 days'=>'پچھلے 7 دن','Last 30 days'=>'پچھلے 30 دن','All time'=>'تمام وقت','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'پیش رفت، فراہم کنندہ، اور ماڈل کے لحاظ سے ٹوکن استعمال کی مقدار۔ ہر کامیاب AI کال پر ریکارڈ کیا جاتا ہے؛ ٹیسٹ کنکشن پنگز کو جان بوجھ کر خارج کیا گیا ہے تاکہ وہ کل کو متاثر نہ کریں۔ بنیادی جدول روزانہ کا تجزیہ کرتی ہے — اسے دیکھنے کے لیے نیچے ایک ونڈو منتخب کریں۔','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'ابھی تک AI استعمال کا ریکارڈ نہیں ہے۔ جب بھی کوئی ایڈیٹر ترجمہ کرتا ہے، میٹا تفصیل تیار کرتا ہے، یا کوئی اور AI خصوصیت استعمال کرتا ہے، تو کل یہاں ظاہر ہوں گے۔','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'منتخب ونڈو (%s) میں AI استعمال کا ریکارڈ نہیں ہے۔ اوپر ایک وسیع رینج منتخب کریں۔','Feature'=>'خصوصیت','Provider'=>'فراہم کنندہ','Model'=>'ماڈل','Requests'=>'درخواستیں','Input tokens'=>'انپٹ ٹوکنز','Output tokens'=>'آؤٹ پٹ ٹوکنز','Total tokens'=>'کل ٹوکنز','Total'=>'کل','API Keys'=>'API کیز','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'کیز کو AES-256-CBC کے ساتھ انکرپٹ کیا جاتا ہے قبل اس کے کہ وہ ورڈپریس کے ڈیٹا بیس میں محفوظ ہوں۔ انکرپشن کا راز آپ کے ورڈپریس کے تصدیقی نمک (wp-config.php) سے حاصل کیا جاتا ہے، اس لیے سادہ متن کی کیز کبھی بھی ڈیٹا بیس کو نہیں چھوتی۔','API Key'=>'API کلید','Paste your API key…'=>'اپنی API کلید چسپاں کریں…','✓ Configured'=>'✓ ترتیب دیا گیا','✗ Not configured'=>'✗ ترتیب نہیں دیا گیا','Test connection'=>'کنکشن کا ٹیسٹ کریں','Leave blank to keep the existing key. Enter a new value to replace it.'=>'خالی چھوڑیں تاکہ موجودہ کلید کو برقرار رکھا جا سکے۔ اسے بدلنے کے لیے ایک نئی قیمت درج کریں۔','Remove stored key'=>'محفوظ شدہ کلید کو ہٹائیں','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'یہ کلید فی الحال ایک سرور %s سے فراہم کی جا رہی ہے اور اسے یہاں سے ہٹایا نہیں جا سکتا۔ اسے اوور رائیڈ کرنے کے لیے اوپر ایک نئی کلید درج کریں۔','environment variable'=>'ماحولیاتی متغیر','PHP constant'=>'PHP مستقل','Alternative (server-side):'=>'متبادل (سرور-سائیڈ):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'آپ کلیدوں کو مستقل یا ماحولیاتی متغیر کے طور پر بھی تعریف کر سکتے ہیں (مثلاً wp-config.php میں)۔ یہ ذرائع خودکار طور پر استعمال ہوتے ہیں جب کوئی ڈیٹا بیس کلید محفوظ نہیں ہوتی۔','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'ایک کسٹم انکرپشن خفیہ کا استعمال کرنے کے لیے (جو کہ حاصل شدہ wp_salt قیمت کے بجائے ہے)، اسے wp-config.php میں شامل کریں:','Unknown provider.'=>'نامعلوم فراہم کنندہ۔','No API key configured for this provider.'=>'اس فراہم کنندہ کے لیے کوئی API کلید ترتیب نہیں دی گئی۔','Could not instantiate the provider.'=>'فراہم کنندہ کو شروع نہیں کیا جا سکا۔','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'فراہم کنندہ نے کوئی متن واپس نہیں کیا۔ تفصیلی ناکامی کی وجہ کے لیے ورڈپریس کی غلطی لاگ چیک کریں۔','Behavior'=>'رویہ','Block Editor'=>'بلوک ایڈیٹر','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge دو Gutenberg خصوصیات کو محدود کرتا ہے تاکہ زبانوں کے درمیان اداریہ رویہ مستقل رہے۔ یہاں شامل ہوں جب آپ کو مکمل Gutenberg / FSE صلاحیتوں کی ضرورت ہو۔','Block locking'=>'بلوک لاک کرنا','Allow editors to lock individual blocks'=>'ایڈیٹرز کو اجازت دیں کہ وہ انفرادی بلاکس کو لاک کریں','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'s canLockBlocks کو دوبارہ فعال کرتا ہے۔ یہ اداریہ ٹیمپلیٹس کے لیے مفید ہے جنہیں مخصوص بلاکس کو حرکت دینے یا حذف کرنے سے روکنا ہوتا ہے۔','Template mode'=>'ٹیمپلیٹ موڈ','Allow Gutenberg template-editing mode on post screens'=>'پوسٹ اسکرین پر Gutenberg ٹیمپلیٹ ایڈیٹنگ موڈ کی اجازت دیں','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode کو دوبارہ فعال کرتا ہے۔ یہ مکمل سائٹ ایڈیٹنگ ورک فلو کے لیے بنیادی ہے جہاں پوسٹ سطح کے ٹیمپلیٹ اوور رائیڈز ارادتا ہوتے ہیں۔','Compliance Preset'=>'مطابقت کا پری سیٹ','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'قانونی، ریگولیٹری، طبی، یا تکنیکی مواد کے لیے سخت تحفظ کا موڈ۔ جب فعال ہو، ہر AI خصوصیت کم سیمپلنگ درجہ حرارت استعمال کرتی ہے اور اپنے نظام پرامپٹ کے نیچے اضافی متن شامل کرتی ہے — اصطلاحات، آرٹیکل نمبرز، یونٹس، برانڈ نام، اور ریگولیٹری زبان کو حرف بہ حرف محفوظ رکھا جاتا ہے، نہ کہ پیرا فریز کیا جاتا ہے۔','Global AI preset'=>'عالمی AI پری سیٹ','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6، فی خصوصیت','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'یہ سائٹ بھر میں تمام خصوصیات کے لیے ڈیفالٹ AI رویہ مقرر کرتا ہے۔ انفرادی پوسٹس اس کو ترجمانی اور مواد تخلیق کے لیے اوور رائیڈ کر سکتی ہیں، جو کہ Lingua Forge میٹا باکس کے ذریعے ہے۔','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'معیاری ہر خصوصیت کے اپنے مخصوص درجہ حرارت کا استعمال کرتا ہے: ترجمہ T=0.2 (مستحکم)، فوری ترجمہ T=0.4، مواد تخلیق T=0.6 (تخلیقی)۔ دیگر پری سیٹس تمام خصوصیات پر ایک مقررہ درجہ حرارت لاگو کرتی ہیں۔','Technical / Scientific instructions'=>'تکنیکی / سائنسی ہدایات','Legal / Compliance instructions'=>'قانونی / تعمیل ہدایات','Creative / Marketing instructions'=>'تخلیقی / مارکیٹنگ ہدایات','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'خالی چھوڑیں تاکہ بلٹ ان ڈیفالٹ استعمال کیا جا سکے۔ محفوظ شدہ اوور رائیڈ کو صاف کرنے سے اگلی بار ڈیفالٹ بحال ہو جائے گا۔','View built-in default'=>'بلٹ ان ڈیفالٹ دیکھیں','Translation Memory'=>'ترجمہ یادداشت','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'ترجمہ شدہ مساوی کو بلاک سطح پر کیش کریں تاکہ قابل استعمال مواد (مشترکہ فوٹرز، سائیڈبارز، ایکورڈینز، قانونی سیکشنز) ہر بار API کال نہ کریں۔ فعال ہونے پر، ترجمہ کا عمل ہر پوسٹ کو بلاکس میں پارس کرتا ہے، ہر بلاک کو کیش میں دیکھتا ہے، اور صرف ان بلاکس کو AI کو بھیجتا ہے جو کیش میں نہیں ہیں۔ گلاسری میں ترمیم اور تعمیل پری سیٹ میں تبدیلیاں خود بخود متاثرہ کیش شدہ ترجمہ کو منسوخ کرتی ہیں۔ اعداد و شمار دیکھیں اور کیش صاف کریں۔','Enable block-level translation cache reuse across posts'=>'پوسٹس کے درمیان بلاک سطح کی ترجمہ کیش کا استعمال فعال کریں','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'اس وقت ان پوسٹس کے لیے چھوڑ دیا گیا ہے جو بلاک-تبصرہ خصوصیت کے پلیس ہولڈرز استعمال کرتی ہیں (wp:details خلاصہ فیلڈز، وغیرہ) — یہ موجودہ سنگل-کال ترجمہ راستے سے گرتی ہیں۔','General'=>'عام','Light'=>'ہلکا','Meta Description, Excerpt Generator'=>'میٹا تفصیل، اقتباس جنریٹر','Quality'=>'معیار','Translation, Content Generator'=>'ترجمہ، مواد تخلیق','Active Provider'=>'فعال فراہم کنندہ','Currently inherited from the %s constant. Selecting a value here will override it.'=>'اس وقت %s مستقل سے وراثت میں ملا ہوا ہے۔ یہاں ایک قیمت منتخب کرنے سے اسے اوور رائیڈ کیا جائے گا۔','Models'=>'ماڈلز','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'خصوصیات کو دو سطحوں میں گروپ کیا گیا ہے۔ ہر سطح اور فراہم کنندہ کے لیے بالکل درست ماڈل شناخت کنندہ درج کریں۔ خالی چھوڑیں تاکہ بلٹ ان ڈیفالٹ استعمال کیا جا سکے۔ صرف فعال فراہم کنندہ کے ماڈلز کو رن ٹائم پر کال کیا جاتا ہے — اگر آپ سوئچ کرنے کا ارادہ رکھتے ہیں تو دیگر کو پہلے سے ترتیب دیں۔','active'=>'فعال','overridden'=>'اوور رائیڈ کیا گیا','Tip: to reset a model to the built-in default, clear the field and save.'=>'اشارہ: ایک ماڈل کو بلٹ ان ڈیفالٹ پر ری سیٹ کرنے کے لیے، فیلڈ کو صاف کریں اور محفوظ کریں۔','Glossary'=>'گلاسری','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'زبان کے جوڑے کے مطابق صارف کے زیر انتظام اصطلاحات کی جدول۔ اندراجات ترجمہ نظام کے اشارے میں شامل کی جاتی ہیں تاکہ AI ترجیحی اصطلاحات کو مستقل استعمال کرے — شعبہ جاتی الفاظ ("kWp", "PPA", "interconnection point")، برانڈ کے نام جو ترجمہ نہیں ہونے چاہئیں، اور معیاری ضابطہ بندی کے جملے کے لیے اہم۔ دونوں زبان کے فیلڈز اختیاری ہیں: "ماخذ زبان" کو خالی چھوڑیں تاکہ یہ اندراج کسی بھی زبان سے ترجمہ کرنے کے باوجود لاگو ہو؛ "ہدف زبان" کو خالی چھوڑیں تاکہ یہ تمام ہدف زبانوں پر ایک ساتھ لاگو ہو۔','Glossary entry added.'=>'مفہومیہ داخلہ شامل کیا گیا۔','Glossary entry removed.'=>'مفہومیہ داخلہ ہٹا دیا گیا۔','Could not add entry: source term and target term are required.'=>'داخلہ شامل نہیں کیا جا سکا: ماخذ اصطلاح اور ہدف اصطلاح ضروری ہیں۔','Could not save the glossary entry.'=>'مفہومیہ داخلہ محفوظ نہیں کیا جا سکا۔','Source language'=>'ماخذ زبان','— Any —'=>'— کوئی بھی —','Target language'=>'ہدف زبان','— Any target —'=>'— کوئی بھی ہدف —','Filter'=>'فلٹر','Reset'=>'ری سیٹ','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'موجودہ فلٹر سے کوئی مفہومیہ داخلہ مطابقت نہیں رکھتا۔ تمام داخلوں کو دیکھنے کے لیے فلٹر صاف کریں، یا نیچے ایک نیا داخلہ شامل کریں۔','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'ابھی تک کوئی مفہومیہ داخلہ نہیں ہے۔ ترجمہ میں اصطلاحات کے نفاذ کے لیے نیچے ایک شامل کریں۔','Source term'=>'ماخذ اصطلاح','Target term'=>'ہدف اصطلاح','Source lang'=>'ماخذ زبان','Target lang'=>'ہدف زبان','Notes'=>'نوٹس','any'=>'کچھ بھی','Delete this glossary entry?'=>'کیا آپ اس مفہومیہ داخلہ کو حذف کرنا چاہتے ہیں؟','Delete'=>'حذف کریں','Add new entry'=>'نیا داخلہ شامل کریں','The phrase as it appears in the source text.'=>'ماخذ متن میں جیسا ظاہر ہوتا ہے۔','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'ترجمہ میں یہ کس طرح ظاہر ہونا چاہیے۔ AI کو ہدایت دینے کے لیے ماخذ اصطلاح کے طور پر وہی قدر ٹائپ کریں تاکہ اسے حرف بہ حرف محفوظ رکھا جائے۔','— Any source language —'=>'— کوئی بھی ماخذ زبان —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'برانڈ کے نام اور زبان سے آزاد اصطلاحات کے لیے خالی چھوڑیں جنہیں کسی بھی زبان سے ترجمہ کرنے کے باوجود نافذ کیا جانا چاہیے۔','— Any target language —'=>'— کوئی بھی ہدف زبان —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'اس داخلہ کو تمام ہدف زبانوں پر لاگو کرنے کے لیے خالی چھوڑیں — برانڈ کے نام، مخففات، اور اصطلاحات کے لیے جو ہر ترجمہ میں حرف بہ حرف محفوظ رہنی چاہئیں۔','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'ایڈیٹرز کے لیے اختیاری سیاق و سباق (مثلاً "ASIC = ایپلیکیشن-خصوصی انٹیگریٹڈ سرکٹ؛ تکنیکی سیاق و سباق میں انگریزی میں محفوظ رکھیں").','Add entry'=>'داخلہ شامل کریں','Limits'=>'حدیں','Authors and above (edit_published_posts)'=>'مصنفین اور اوپر (edit_published_posts)','Contributors and above — default (edit_posts)'=>'شریک کار اور اوپر — ڈیفالٹ (edit_posts)','Editors and above (edit_others_posts)'=>'ایڈیٹرز اور اوپر (edit_others_posts)','Administrators only (manage_options)'=>'صرف ایڈمنسٹریٹرز (manage_options)','AI Limits & Security'=>'AI کی حدیں اور سیکیورٹی','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'سائٹ کی AI استعمال کی حد مقرر کریں اور ان صارف کرداروں کو محدود کریں جو ادائیگی شدہ AI کالز کو چلا سکتے ہیں۔ یہ پہلے سے موجود فی صارف شرح حد (30 درخواستیں / منٹ، ہارڈ کوڈڈ) کے اوپر بیٹھتی ہے جو ایک صارف کے رن وے لوپ سے بچاؤ کرتی ہے۔','Daily request limit'=>'روزانہ درخواست کی حد','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC دن کے لیے سائٹ بھر میں AI درخواستوں کی چھت (یہ دونوں ٹولبار ترجمے اور بلاک ترمیمات کو شمار کرتا ہے)۔ کاؤنٹر UTC آدھی رات کو ری سیٹ ہوتا ہے۔ اسے 0 پر سیٹ کریں تاکہ حد کو غیر فعال کیا جا سکے۔','Minimum role'=>'کم از کم کردار','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'سب سے کم ورڈپریس صلاحیت جو AI خصوصیات کو فعال کرنے کی اجازت دیتی ہے۔ اس کو سخت کرنا ملٹی-مصنف سائٹس پر شریک کار یا آزمائشی اکاؤنٹس کو ادائیگی شدہ AI کالز چلانے سے روکتا ہے۔ فیچر کے مطابق override کریں via the linguaforge_required_capability فلٹر۔','Translation Limits'=>'ترجمہ کی حدیں','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'کنٹرول کریں کہ مواد کو AI کو کتنا بھیجا جائے اور جواب کتنا بڑا ہو سکتا ہے۔ ایک فیلڈ کو خالی چھوڑیں تاکہ اندرونی ڈیفالٹ استعمال ہو (جیسے پلیس ہولڈر میں دکھایا گیا ہے)۔ اگر بڑی صفحات کاٹ دی جا رہی ہیں تو ان اقدار کو بڑھائیں؛ API کے اخراجات کم کرنے کے لیے انہیں کم کریں۔','Model tier'=>'ماڈل سطح','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'معیار (ڈیفالٹ — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'ہلکا (تیز اور کم قیمت — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'مکمل صفحہ ترجمہ کے لیے کون سا ماڈل استعمال کرنا ہے۔ معیار اوپر دی گئی ماڈلز ٹیبل میں ترتیب دیا گیا ماڈل استعمال کرتا ہے اور درست، طویل شکل کے ترجمہ کے لیے تجویز کیا جاتا ہے۔ صرف رفتار یا لاگت کو ترجیح دینے اور مواد مختصر ہونے کی صورت میں Light پر سوئچ کریں۔','Max output tokens'=>'زیادہ سے زیادہ آؤٹ پٹ ٹوکن','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'ایک ترجمہ جواب میں AI زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ اگر ترجمہ خاموشی سے ختم ہو رہا ہے، تو اس قدر کو بڑھائیں۔ ڈیفالٹ: 16,000۔','Max input characters'=>'زیادہ سے زیادہ ان پٹ حروف','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'ای اے آئی کو بھیجے گئے پوسٹ مواد کی زیادہ سے زیادہ تعداد۔ 0 کا مطلب کوئی حد نہیں — مکمل مواد ہمیشہ بھیجا جاتا ہے (تجویز کردہ)۔ ایک غیر صفر قیمت مقرر کریں صرف اگر آپ کے فراہم کنندہ کے پاس سخت سیاق و سباق کی ونڈو ہے۔ جب مواد کاٹ دیا جاتا ہے تو PHP ایرر لاگ میں ایک وارننگ لکھی جاتی ہے۔','Quick Translation'=>'جلدی ترجمہ','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'جلدی ترجمہ کو اسنپٹ/چنک موڈ کے لیے استعمال کیا جاتا ہے — شارٹ پیغامات کو ٹول بار، ایڈیٹر، یا بلاک پاپ اوور سے مطالبہ پر ترجمہ کیا جاتا ہے۔ یہ مکمل صفحہ ترجمہ سے ایک علیحدہ، ہلکی سی ترتیب استعمال کرتا ہے تاکہ جواب تیز اور کم قیمت رہیں۔','Light (default — fast and cost-effective)'=>'ہلکا (پہلا — تیز اور کم قیمت)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'معیار (سونٹ / GPT-4o / جیمینی پرو)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'ہلکی سطح تیز ماڈل استعمال کرتی ہے جو اوپر دی گئی ماڈلز ٹیبل میں ترتیب دیا گیا ہے (پہلا: ہائیکو / فلیش)۔ اگر آپ کو اسنپٹ کے لیے مکمل صفحہ کے مترادف ترجمہ کی درستگی چاہیے تو معیار پر سوئچ کریں۔','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'ای اے آئی ہر جلدی ترجمہ پر زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ ڈیفالٹ: 2،000۔','Maximum characters accepted from the input field. Default: 8 000.'=>'ان پٹ فیلڈ سے قبول شدہ زیادہ سے زیادہ کردار۔ ڈیفالٹ: 8،000۔','Content Generator'=>'مواد پیدا کرنے والا','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'ای اے آئی مواد پیدا کرنے والے فیچر کے لیے ٹوکن بجٹ اور ان پٹ حدود کو کنٹرول کرتا ہے۔ بلینک فیلڈز کو چھوڑیں تاکہ بلٹ ان ڈیفالٹس استعمال ہوں۔','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'ای اے آئی ہر پیداوار رن پر زیادہ سے زیادہ ٹوکن پیدا کر سکتا ہے۔ اگر مکمل مضامین کاٹ رہے ہیں تو اسے بڑھائیں۔ ڈیفالٹ: 8،192۔','Max hints characters'=>'اشارہ کے کردار زیادہ سے زیادہ','Maximum characters read from the Hints field. Default: 2 000.'=>'اشاروں کے میدان سے پڑھنے کے لیے زیادہ سے زیادہ کردار۔ ڈیفالٹ: 2،000۔','Max context characters'=>'مکمل سیاق و سباق کے کردار زیادہ سے زیادہ','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'جب کوئی اشارہ فراہم نہیں کیا جاتا تو ای اے آئی کو پاس کیے گئے موجودہ پوسٹ مواد کے زیادہ سے زیادہ کردار۔ ڈیفالٹ: 6،000۔','Maintenance'=>'مرمت','Language Overrides'=>'زبان کی تبدیلی','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'تیسری پارٹی پلگ ان کے اسٹرنگز کو اوور رائڈ کرنے کے لیے مرتب شدہ .mo فائلیں اپ لوڈ کریں — مثال کے طور پر، ایک کسٹم ویک بُکنگ ترجمہ جو "کمرہ" کے بجائے "اپارٹمنٹ" استعمال کرتا ہے۔ فائلیں ورڈپریس کے نام کی قاعدہ کی پیروی کرتی ہیں: {textdomain}-{locale}.mo (مثلاً vikbooking-ca.mo)۔ یہ اپ لوڈز فولڈر میں محفوظ ہوتی ہیں اور پلگ ان اپ ڈیٹس کے دوران برقرار رہتی ہیں۔','Override file uploaded successfully.'=>'اوور رائڈ فائل کامیابی سے اپ لوڈ ہوئی۔','Override file deleted.'=>'اوور رائڈ فائل حذف کر دی گئی۔','No file was selected.'=>'کوئی فائل منتخب نہیں کی گئی۔','Only .mo files are accepted.'=>'صرف .mo فائلیں قبول کی جاتی ہیں۔','The upload failed — please try again.'=>'اپ لوڈ ناکام رہا — براہ کرم دوبارہ کوشش کریں۔','Could not save the file. Check that the uploads folder is writable.'=>'فائل کو محفوظ نہیں کیا جا سکا۔ چیک کریں کہ اپ لوڈز فولڈر قابل تحریر ہے۔','Invalid filename.'=>'غلط فائل کا نام۔','Security check failed — file path is not permitted.'=>'سیکیورٹی چیک ناکام — فائل کا راستہ اجازت یافتہ نہیں ہے۔','An unknown error occurred.'=>'ایک نامعلوم غلطی پیش آئی۔','Text domain / locale'=>'ٹیکسٹ ڈومین / لوکیل','Files'=>'فائلیں','Size'=>'سائز','Delete all files for this override (both .mo and .po)?'=>'اس اوور رائڈ کے لیے تمام فائلیں حذف کریں (دونوں .mo اور .po)؟','No override files uploaded yet.'=>'ابھی تک کوئی اوور رائڈ فائل اپ لوڈ نہیں کی گئی۔','Upload .mo file'=>'.mo فائل اپ لوڈ کریں','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'صرف مرتب شدہ .mo فائلیں قبول کی جاتی ہیں۔ فائل کا نام {textdomain}-{locale}.mo کے پیٹرن کی پیروی کرنا چاہیے۔ ایک ہی نام کی فائل اپ لوڈ کرنے سے وہ تبدیل ہو جائے گی۔','Upload Override'=>'اوور رائڈ اپ لوڈ کریں','Loco Translate — Copy to Safe Storage'=>'لوکو ترجمہ — محفوظ اسٹوریج پر کاپی کریں','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'لوکو ترجمہ اپنی مرضی کے ترجمے wp-content/languages/loco/ میں محفوظ کرتا ہے — ایک جگہ جو کہ ایک WP کور اپ ڈیٹ، پلگ ان کی دوبارہ تنصیب، یا اگر لوکو ترجمہ خود کو ہٹا دیا جائے تو خاموشی سے مٹ سکتی ہے۔ یہاں فائلیں کاپی کرنے سے وہ Lingua Forge i18n-overrides ڈائریکٹری میں منتقل ہو جاتی ہیں، جو ان تمام واقعات کے دوران برقرار رہتی ہے اور ہر درخواست پر خود بخود لوڈ ہوتی ہے۔','File copied to safe storage successfully.'=>'فائل کامیابی سے محفوظ اسٹوریج میں کاپی ہو گئی۔','Source file not found.'=>'ماخذ فائل نہیں ملی۔','Could not copy the file. Check that the uploads folder is writable.'=>'فائل کو کاپی نہیں کیا جا سکا۔ چیک کریں کہ اپ لوڈز فولڈر قابل تحریر ہے۔','Invalid file reference.'=>'غلط فائل کا حوالہ۔','Type'=>'قسم','✓ In safe storage'=>'✓ محفوظ اسٹوریج میں','Copy to safe storage'=>'محفوظ اسٹوریج پر کاپی کریں','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'ابھی تک کوئی کسٹم لوکو ترجمہ فائلیں نہیں ملی ہیں۔ یہ یہاں ظاہر ہوتی ہیں جب آپ لوکو ترجمہ میں ترجمہ محفوظ کرتے ہیں۔','AI Cache'=>'ای اے آئی کیش','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge اپنی AI سے تیار کردہ ترجمے، میٹا تفصیلات، اقتباسات، اور پیدا کردہ مواد کو کیش کرتا ہے تاکہ بغیر تبدیلی کے ان پٹ پر کوئی پیڈ API کال دوبارہ نہ ہو۔ کیش شدہ اندراجات خود بخود منسوخ ہو جاتے ہیں جب ان کے ان پٹ بدل جاتے ہیں۔ کیش کو دستی طور پر صاف کریں تاکہ ڈیٹا بیس کی جگہ واپس حاصل کریں، فراہم کنندہ تبدیل کرنے یا پرامپٹ ٹیمپلیٹس میں ترمیم کے بعد دوبارہ ہم آہنگی کریں، یا کسی کیش سے متعلق مسئلے کو حل کریں۔','AI cache cleared. %d entry was removed.'=>'ای اے آئی کیش صاف کر دی گئی۔ %d اندراج ہٹا دی گئی۔' . "\0" . 'ای اے آئی کیش صاف کر دی گئی۔ %d اندراجات ہٹا دی گئی ہیں۔','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'تمام کیش شدہ AI نتائج کو صاف کریں؟ مستقبل کی درخواستیں تازہ API کالز کو متحرک کریں گی جب تک کہ کیش دوبارہ نہ بن جائے۔','Clear AI Cache'=>'ای اے آئی کیشے صاف کریں','Debug Files'=>'ڈیبگ فائلیں','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'جب ڈیبگ لاگنگ فعال ہوتی ہے (نیچے ٹوگل کے ذریعے یا wp-config.php میں LINGUAFORGE_AI_DEBUG کو ڈیفائن کرکے)، ترجمہ اور ایف ایس ای ٹیمپلیٹ ترجمہ خصوصیات اپنی خام اے آئی پرامپٹس اور جوابات کو دشواری حل کے لیے ڈسک پر لکھتی ہیں۔ اس سیکشن کا استعمال اس آؤٹ پٹ کی نگرانی کے لیے کریں اور اسے صاف کریں جب آپ کو ضرورت ہو — فائلیں بڑے صفحات پر تیزی سے بڑھ سکتی ہیں۔ ہدف ڈائریکٹری کو linguaforge_debug_dir فلٹر کے ذریعے ترتیب دیں۔','Debug files cleared. %d file was removed.'=>'ڈیبگ فائلیں صاف کی گئی۔ %d فائل ہٹا دی گئی۔' . "\0" . 'ڈیبگ فائلیں صاف کی گئی۔ %d فائلیں ہٹا دی گئی ہیں۔','Debug logging enabled.'=>'ڈیبگ لاگنگ فعال ہے۔','Debug logging disabled.'=>'ڈیبگ لاگنگ غیر فعال ہے۔','Debug logging'=>'ڈیبگ لاگنگ','Write AI prompts and responses to disk for troubleshooting'=>'مسئلے حل کے لیے اے آئی پرامپٹس اور جوابات کو ڈسک پر لکھیں','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php میں LINGUAFORGE_AI_DEBUG مستقل کے ذریعے زبردستی آن۔ اس لائن کو ہٹا کر اس ٹوگل کو یہاں سے کنٹرول کریں۔','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php میں LINGUAFORGE_AI_DEBUG مستقل کے ذریعے زبردستی آف۔ اس لائن کو ہٹا کر اس ٹوگل کو یہاں سے کنٹرول کریں۔','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'فائلیں نیچے دیے گئے ڈائریکٹری میں آتی ہیں۔ ترجمہ کے مسائل کی تشخیص کے لیے مفید — ایک بار جب آپ کو ضرورت ہو تو بند کریں تاکہ فائلیں جمع نہ ہوں۔ آپ اسے wp-config.php سے بھی فورس کر سکتے ہیں `define( \'LINGUAFORGE_AI_DEBUG\', true );` کے ساتھ جو ٹوگل کو اوور رائیڈ کرتا ہے۔','Currently:'=>'اس وقت:','✓ Enabled'=>'✓ فعال','✗ Disabled'=>'✗ غیر فعال','Directory'=>'ڈائریکٹری','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'ڈیبگ آؤٹ پٹ کو غیر عوامی مقام پر ری ڈائریکٹ کرنے کے لیے linguaforge_debug_dir کے ساتھ فلٹر کریں۔','.txt file(s) in the directory'=>'.txt فائل(یں) ڈائریکٹری میں','Save Debug Setting'=>'ڈیبگ سیٹنگ محفوظ کریں','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'کیا آپ ڈیبگ ڈائریکٹری میں تمام .txt فائلیں حذف کرنا چاہتے ہیں؟ خود ڈائریکٹری باقی رہے گی تاکہ مستقبل میں ڈیبگ لکھائی آسانی سے ہو سکے۔ آپ اسے wp-config.php سے بھی فورس کر سکتے ہیں `define( \'LINGUAFORGE_AI_DEBUG\', true );` کے ساتھ جو ٹوگل کو اوور رائیڈ کرتا ہے۔','Clear Debug Files'=>'ڈیبگ فائلیں صاف کریں','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'پوسٹس کے درمیان مشترکہ بلاک ترجمہ کیش۔ سیٹنگز → رویہ میں آن/آف کریں۔ نیچے دیے گئے اعداد و شمار دکھاتے ہیں کہ فی الحال کیا کیش ہے؛ صفائی ہر بلاک کو اگلی درخواست پر دوبارہ ترجمہ کرنے پر مجبور کرتی ہے (ماڈلز اپ گریڈ کرنے یا ڈیٹا بیس کی جگہ بازیابی کے لیے مفید)۔','Translation Memory cleared. %d cached block was removed.'=>'ترجمہ یادداشت صاف کی گئی۔ %d کیش شدہ بلاک ہٹا دیا گیا۔' . "\0" . 'ترجمہ یادداشت صاف کی گئی۔ %d کیش شدہ بلاک ہٹا دیے گئے۔','Status'=>'حالت','— toggle in Settings → Behavior.'=>'— سیٹنگز → رویہ میں ٹوگل۔','Cached blocks'=>'کیش شدہ بلاکس','Cumulative cache hits'=>'مجموعی کیش ہٹس','(avg %.1f hits/block)'=>'(اوسط %.1f ہٹس/بلاک)','Oldest entry'=>'سب سے پرانا اندراج','Newest entry'=>'سب سے نیا اندراج','Approximate size'=>'تقریبی سائز','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'کیا آپ ترجمہ یادداشت کو مکمل طور پر صاف کرنا چاہتے ہیں؟ مستقبل کے ترجمے اسے دوبارہ بنائیں گے۔','Clear Translation Memory'=>'ترجمہ یادداشت صاف کریں','Uninstall Behaviour'=>'رویے ان انسٹال کریں','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'جب ایڈمنسٹریٹر Plugins → Installed Plugins → Delete سے پلگ ان کو حذف کرتا ہے تو یہ کنٹرول کرتا ہے کہ کیا ہوتا ہے۔ پلگ ان کی سیٹنگز اور اے آئی کیش ہمیشہ ہٹائے جاتے ہیں۔ زبان کی تفویض اور ترجمہ کے تعلقات کو بطور ڈیفالٹ رکھا جاتا ہے تاکہ حادثاتی ان انسٹال یا دوبارہ انسٹال پر وہیں سے شروع کیا جا سکے۔','Uninstall setting saved.'=>'ان انسٹال سیٹنگ محفوظ کی گئی۔','Delete content data on uninstall'=>'ان انسٹال پر مواد کا ڈیٹا حذف کریں','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'جب پلگ ان ان انسٹال کیا جائے تو زبان کی تفویض، ترجمہ کے تعلقات، میٹا تفصیلات، گلاسری، اور ترجمہ یادداشت بھی حذف کریں۔','Warning:'=>'خبردار:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'اگر چیک کیا گیا، تو پلگ ان ان انسٹال کرنے سے تمام زبان کی تفویض، ترجمہ کے تعلقات، میٹا تفصیلات، صفحات کے پری سیٹ، اے آئی گلاسری، اور ترجمہ یادداشت ہمیشہ کے لیے حذف ہو جائیں گی۔ یہ عمل واپس نہیں لیا جا سکتا۔ جب تک کہ آپ مکمل طور پر ملٹی لنگول سپورٹ کو ہٹا رہے ہوں، اسے ان چیک چھوڑیں۔','Save Uninstall Setting'=>'ان انسٹال سیٹنگ محفوظ کریں','Router'=>'روٹر','Primary language saved.'=>'پہلی زبان محفوظ کی گئی۔','Permalink rules flushed successfully.'=>'پرم لنک قواعد کامیابی سے فلش ہو گئے۔','Primary Language'=>'پہلی زبان','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'پہلی زبان ہمیشہ آپ کی سائٹ کے روٹ پر سروس کی جاتی ہے — راستہ موڈ میں URL پیشگی نہیں، سب ڈومین موڈ میں زبان کا سب ڈومین نہیں۔ دیگر زبانیں یا تو /lang/ راستہ پیشگی استعمال کرتی ہیں (مثلاً example.com/de/) یا زبان کا سب ڈومین (مثلاً de.example.com)، جو نیچے دی گئی URL ساخت کی ترتیب پر منحصر ہے۔','Primary language'=>'پہلی زبان','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'پہلی زبان تبدیل کرنے کے بعد، URL راؤٹنگ کو اپ ڈیٹ کرنے کے لیے پرم لنکس کو فلش کریں (نیچے سیکشن)۔','URL structure'=>'URL ساخت','Path prefix — example.com/de/'=>'پاتھ پری فکس — example.com/de/','Subdomain — de.example.com/'=>'ذیلی ڈومین — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'ذیلی ڈومین موڈ آپ کے ویب سرور کو تمام زبان کے ذیلی ڈومینز (مثلاً de.example.com) کو اس ورڈپریس تنصیب کی طرف اشارہ کرنے کی ضرورت ہے۔ موڈ تبدیل کرنے کے بعد، permalink قواعد کو فلش کریں اور کسی بھی کیش کو صاف کریں۔ اگر آپ کا ہوم یو آر ایل www شامل ہے (مثلاً www.example.com)، تو lf_base_domain فلٹر کا استعمال کریں تاکہ صرف بنیادی ڈومین سیٹ کیا جا سکے تاکہ ذیلی ڈومینز صحیح طریقے سے بنیں۔','Browser language redirect'=>'براؤزر زبان ری ڈائریکشن','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'براؤزر کے Accept-Language ہیڈر کی بنیاد پر زائرین کو ان کی ترجیحی زبان پر ری ڈائریکٹ کریں','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'جب فعال ہو، تو پہلی بار آنے والے زائرین جن کے پاس زبان کا کوکی نہیں اور URL میں زبان کا پیش لفظ نہیں، سب سے قریب ملنے والی زبان کے ورژن پر ری ڈائریکٹ کیے جاتے ہیں۔ اگر براؤزر کی ترجیحی زبان فعال روٹر زبانوں میں شامل نہیں ہے، تو ری ڈائریکٹ کو چھوڑ دیا جاتا ہے۔ جب کوئی زائرین سوئچر کے ذریعے زبان منتخب کرتا ہے، تو کوکی ترجیح حاصل کرتی ہے اور براؤزر ہیڈر کو مستقبل کے دوروں پر نظر انداز کیا جاتا ہے۔','Save Router Settings'=>'روٹر سیٹنگز محفوظ کریں','Flush Permalinks'=>'پرم لنکس کو فلش کریں','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'ورڈپریس کے ری رائٹ قواعد کو دوبارہ پیدا کرتا ہے تاکہ URL پری فکسز، زبان مخصوص سلگ، اور آرکائیو ری رائٹس سب ہم آہنگ ہوں۔ بنیادی زبان تبدیل کرنے یا نئی زبان کی حمایت شامل کرنے کے بعد ضروری ہے۔','Flush Permalink Rules'=>'پرم لنک قواعد کو فلش کریں','Active Languages'=>'فعال زبانیں','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'روٹر کو معلوم زبانیں (انسٹال شدہ ورڈپریس لوکیل پیکز اور بنیادی زبان سے حاصل شدہ)۔ مزید زبانیں دستیاب کرنے کے لیے ذیل کے سیکشن میں اضافی زبان پیکز انسٹال کریں۔','%d locale pack installed.'=>'%d لوکیل پیک انسٹال ہے۔' . "\0" . '%d لوکیل پیک انسٹال ہیں۔','Install a Language'=>'ایک زبان انسٹال کریں','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'ورڈپریس.org سے براہ راست ورڈپریس کور زبان پیک ڈاؤن لوڈ اور انسٹال کریں۔ ایک بار انسٹال ہونے کے بعد، لوکیل URL روٹنگ اور AI ترجمہ ورک فلو کے لیے دستیاب ہو جاتا ہے۔ دستیاب زبانوں کی فہرست ضرورت کے مطابق حاصل کی جاتی ہے — اسے لوڈ کرنے کے لیے نیچے بٹن پر کلک کریں۔','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'اس سرور پر زبان کی تنصیب غیر فعال ہے۔ wp-config.php میں DISALLOW_FILE_MODS مستقل سیٹ ہے۔ زبان پیکز کو دستی طور پر WP-CLI کے ذریعے انسٹال کریں: wp language core install de_DE','Load available languages'=>'دستیاب زبانیں لوڈ کریں','— select a language —'=>'— ایک زبان منتخب کریں —','Install'=>'انسٹال کریں','Language Setup'=>'زبان کی سیٹ اپ','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'کوئی ثانوی زبانیں ترتیب نہیں دی گئی ہیں۔ اوپر ایک زبان پیک انسٹال کریں تاکہ ٹیمپلیٹ اسکیفولڈنگ فعال ہو سکے۔','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'اس زبان کا انتخاب کریں تاکہ اس کے FSE ٹیمپلیٹس، ٹیمپلیٹ پارٹس، اور نیویگیشن مینو کو منظم کیا جا سکے۔','Forbidden'=>'ممنوع','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'اس سرور پر زبان کی تنصیب غیر فعال ہے (DISALLOW_FILE_MODS سیٹ ہے)۔','Invalid locale code.'=>'غلط لوکیل کوڈ۔','Language %s installed successfully.'=>'زبان %s کامیابی سے انسٹال ہو گئی ہے۔','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'زبان پیک انسٹالیشن ناکام ہو گئی۔ زبان پہلے سے انسٹال ہو سکتی ہے، لوکیل کوڈ غلط ہو سکتا ہے، یا آپ کا سرور فائل لکھنے سے روک رہا ہے۔','Navigations'=>'نیویگیشنز','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'نیویگیشن ترجمہ کے لیے ایک فعال AI فراہم کنندہ کی ضرورت ہے۔ API کیز ٹیب میں ایک API کلید ترتیب دیں۔','Navigation'=>'نیویگیشن','Action'=>'عمل','Re-translate'=>'دوبارہ ترجمہ کریں','CPT Block Patterns'=>'CPT بلاک پیٹرنز','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'کسٹم پوسٹ ٹائپز کے لیے رجسٹرڈ بلاک پیٹرنز۔ ترجمہ بٹن کا استعمال کریں تاکہ زبان کا ورژن تیار کیا جا سکے۔ ترجمہ شدہ مواد یہاں محفوظ کیا جاتا ہے اور کسی بھی CPT پوسٹ میں کاپی کیا جا سکتا ہے یا سنیپڈ پیٹرن (ری یوزبل بلاک) کے لیے بطور آغاز استعمال کیا جا سکتا ہے۔','Pattern'=>'پیٹرن','Post Types'=>'پوسٹ ٹائپز','✓ Translation saved'=>'✓ ترجمہ محفوظ ہو گیا','View'=>'دیکھیں','Template Parts'=>'ٹیمپلیٹ پارٹس','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'تھیم کے زبان مخصوص نقول۔ ایک بار اسکافولڈ ہونے کے بعد، ٹیمپلیٹس زبان مخصوص پارٹ کا حوالہ دینے کے لیے اپ ڈیٹ ہو جاتے ہیں۔','Part'=>'پارٹ','Status / Actions'=>'حالت / عمل','Fix Links'=>'لنکس کو درست کریں','Fix Nav'=>'نیویگیشن کو درست کریں','Create'=>'بنائیں','Templates'=>'ٹیمپلیٹس','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'فعال تھیم سے سیڈ شدہ FSE ٹیمپلیٹس۔ اسے بنائیں اور پھر سائٹ ایڈیٹر میں تخصیص کریں۔','Actions'=>'عمل','Fix Parts'=>'پارٹس کو درست کریں','Create missing'=>'غائب تخلیق کریں','Translate all'=>'تمام ترجمہ کریں','Fix all parts'=>'تمام حصے درست کریں','Fix all links'=>'تمام روابط درست کریں','Anthropic (Claude)'=>'انتھروپک (کلود)','OpenAI (GPT)'=>'اوپن اے آئی (جی پی ٹی)','Google (Gemini)'=>'گوگل (جمینی)','Testing…'=>'آزمائش جاری ہے…','✓ Connection OK'=>'✓ کنکشن ٹھیک ہے','✗ Failed:'=>'✗ ناکام:','No response from provider — check the error log for details.'=>'پرووائیڈر سے جواب موصول نہیں ہوا — تفصیلات کے لیے ایرر لاگ چیک کریں۔','Network error — could not reach the WordPress AJAX endpoint.'=>'نیٹ ورک کی خرابی — ورڈپریس AJAX اینڈپوائنٹ سے رسائی حاصل نہیں ہو سکی۔','Loading…'=>'لوڈ ہو رہا ہے…','Installing…'=>'انسٹال ہو رہا ہے…','✓ Language installed.'=>'✓ زبان انسٹال ہو گئی ہے۔','✗ Error:'=>'✗ خرابی:','Creating…'=>'درست ہو رہا ہے…','✓ All templates created.'=>'✓ تمام ٹیمپلیٹس بن گئے۔','Some templates could not be created.'=>'کچھ ٹیمپلیٹس نہیں بن سکے۔','✓ All parts created.'=>'✓ تمام حصے بن گئے۔','Some parts could not be created.'=>'کچھ حصے نہیں بن سکے۔','✓ All translated.'=>'✓ سب ترجمہ ہو گیا۔','Some translations failed.'=>'کچھ ترجمے ناکام رہے۔','Review carefully — links and slugs not updated.'=>'احتیاط سے جائزہ لیں — روابط اور سلگ اپ ڈیٹ نہیں ہوئے۔','Fixing…'=>'درست کر رہا ہے…','✓ Links fixed.'=>'✓ روابط درست ہو گئے۔','Some link fixes failed.'=>'کچھ روابط کی درستگی ناکام رہی۔','✓ Parts fixed.'=>'✓ حصے درست ہو گئے۔','Some part fixes failed.'=>'کچھ حصوں کی درستگی ناکام رہی۔','✓ Nav refs fixed.'=>'✓ نیویگیشن ریفرنسز درست۔','Some nav ref fixes failed.'=>'کچھ نیویگیشن ریفرنسز کی درستگی ناکام رہی۔','✓ Pattern translated.'=>'✓ پیٹرن ترجمہ ہو گیا۔','Pattern translation failed.'=>'پیٹرن کا ترجمہ ناکام رہا۔','Hide'=>'چھپائیں','Built-in preset instructions:'=>'بلٹ ان پری سیٹ ہدایات:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'کوئی بلٹ ان ہدایات نہیں — ہر AI فیچر اپنی مخصوص ڈیفالٹس استعمال کرتا ہے۔ اپنی سائٹ کے قواعد شامل کرنے کے لیے نیچے دیے گئے کسٹم پرامپٹ ہدایات کے فیلڈ کو پُر کریں۔','Settings'=>'سیٹنگز','You do not have permission to manage these settings.'=>'آپ کو ان سیٹنگز کو منظم کرنے کی اجازت نہیں ہے۔','Lingua Forge — Settings'=>'لینگوا فورج — سیٹنگز','Settings saved.'=>'سیٹنگز محفوظ ہو گئی ہیں۔','Save Settings'=>'سیٹنگز محفوظ کریں','Standard'=>'معیاری','Technical / Scientific'=>'تکنیکی / سائنسی','Legal / Compliance'=>'قانونی / تعمیل','Creative / Marketing'=>'تخلیقی / مارکیٹنگ','Full Article'=>'مکمل مضمون','Introduction only'=>'صرف تعارف','Structured Outline'=>'ساختی خاکہ','Generate Content'=>'مواد تیار کریں','Hints'=>'اشارات','Key points, ideas, or structure to build from…'=>'اہم نکات، خیالات، یا ساخت جس سے تعمیر کی جائے…','Tone'=>'لہجہ','Output'=>'نتیجہ','Generate Excerpt'=>'خلاصہ تیار کریں','Generate Meta Description'=>'میٹا تفصیل تیار کریں','Translate Content'=>'مواد کا ترجمہ کریں','Mode'=>'طریقہ','Full post'=>'مکمل پوسٹ','Translate chunk'=>'ٹکڑا ترجمہ کریں','Target Language'=>'ہدف زبان','Text to translate'=>'ترجمہ کے لیے متن','Paste a footnote, sentence, or any snippet here…'=>'یہاں ایک نوٹ، جملہ، یا کوئی بھی ٹکڑا چسپاں کریں…','Also generate meta description'=>'میٹا تفصیل بھی تیار کریں','Translated Names'=>'ترجمہ شدہ نام','Name displayed in this language. Leave empty to use the source name.'=>'اس زبان میں دکھایا گیا نام۔ خالی چھوڑیں تاکہ ماخذ کا نام استعمال ہو۔','Too many AI requests. Please retry in %d seconds.'=>'بہت زیادہ AI درخواستیں۔ براہ کرم %d سیکنڈ میں دوبارہ کوشش کریں۔','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'روزانہ AI کوٹہ مکمل ہو گیا (%1$d درخواستیں)۔ %2$s UTC پر ری سیٹ ہوتا ہے۔','View Lingua Forge details'=>'لینگوا فورج کی تفصیلات دیکھیں','View details'=>'تفصیلات دیکھیں','Visit plugin site'=>'پلگ ان کی سائٹ پر جائیں','%d language not yet linked'=>'%d زبان ابھی تک منسلک نہیں ہے' . "\0" . '%d زبانیں ابھی تک منسلک نہیں ہیں','This is the source page. Footnotes are edited directly in the block editor.'=>'یہ ماخذ صفحہ ہے۔ نوٹ براہ راست بلاک ایڈیٹر میں ترمیم کیے جاتے ہیں۔','No source page linked yet.'=>'ابھی تک کوئی ماخذ صفحہ منسلک نہیں ہے۔','The source page has no footnotes.'=>'ماخذ صفحہ میں کوئی نوٹ نہیں ہے۔','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'یہ نوٹس ماخذ صفحہ سے آتے ہیں اور صرف حوالہ کے لیے یہاں دکھائے جاتے ہیں۔ انہیں اس صفحہ میں شامل کریں۔','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d مقامی ٹیمپلیٹ(یں) &#8220;%2$s&#8221; تھیم سے محفوظ ہیں لیکن فی الحال غیر فعال ہیں۔ اگر آپ اس تھیم کو دوبارہ فعال کریں گے تو یہ دوبارہ فعال ہو جائیں گے۔ اپنی ترجمہ کو نئے تھیم میں منتقل کرنے کے لیے، انہیں دوبارہ پیدا کریں <strong>سیٹنگز → Lingua Forge → Router → FSE scaffold</strong> کے ذریعے۔','Scanning posts for broken language links…'=>'ٹوٹے ہوئے زبان کے لنکس کے لیے پوسٹس اسکین کر رہے ہیں…','Re-scanning…'=>'دوبارہ اسکین کر رہے ہیں…','Scan failed: '=>'اسکین ناکام: ','unknown error'=>'نامعلوم غلطی','Scan request failed. Please try again.'=>'اسکین کی درخواست ناکام ہو گئی۔ براہ کرم دوبارہ کوشش کریں۔','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ کوئی <strong>{lang}</strong> پوسٹس نہیں ملی۔ یقینی بنائیں کہ تمام ترجمہ شدہ پوسٹس میں زبان کا میٹا <strong>{lang}</strong> پر سیٹ ہے۔','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong> کے لیے کوئی ٹوٹے ہوئے لنکس یا ٹیمپلیٹ میں غلطیاں نہیں پائی گئیں۔ <strong>{scanned}</strong> پوسٹ/صفحات اسکین کی گئیں — تمام چیک پاس ہو گئے۔ ٹیمپلیٹ پارٹس کے لنکس (ہیڈر، فوٹر، سائیڈبار) یہاں شامل نہیں ہیں — ان کو علیحدہ سے چیک کرنے کے لیے فکس ٹیمپلیٹ پارٹس بٹن استعمال کریں۔','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> خودکار فکس کے قابل لنک','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> لنک جن کا دستی جائزہ لینا ہے','and'=>'اور','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'پائے گئے {parts} <strong>{total}</strong> میں سے <strong>{scanned}</strong> اسکین شدہ پوسٹ/صفحات کے لیے <strong>{lang}</strong>۔','Post'=>'پوسٹ','Links'=>'لنکس','link(s)'=>'لنک','Fix'=>'مرمت کریں','✅ Fixed ({n})'=>'✅ ٹھیک کیا ({n})','⚠ No changes — re-scan?'=>'⚠ کوئی تبدیلی نہیں — دوبارہ اسکین کریں؟','⚠ No changes'=>'⚠ کوئی تبدیلی نہیں','❌ Failed'=>'❌ ناکام','Done — {done} of {total} post(s) fixed.'=>'ہو گیا — {done} میں سے {total} پوسٹیں ٹھیک کی گئیں۔','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} میں کوئی قابلِ تبدیل لنک نہیں تھا — مزید جانچ کے لیے دوبارہ اسکین کریں)','Fixing {n} / {total}…'=>'{n} / {total} کی مرمت جاری ہے…','URL could not be mapped to a post — check the link target exists'=>'URL کو پوسٹ سے منسلک نہیں کیا جا سکا — چیک کریں کہ لنک کا ہدف موجود ہے','No {lang} translation registered (TRID missing)'=>'کوئی {lang} ترجمہ رجسٹرڈ نہیں ہے (TRID غائب ہے)','Translation found but permalink could not be generated'=>'ترجمہ ملا لیکن لنک مستقل لنک تیار نہیں کیا جا سکا','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> پرانی راہ/راہیں','📍 Stale path (page moved)'=>'📍 پرانی راہ (صفحہ منتقل ہو گیا)','{n} stale path(s)'=>'{n} پرانی راہ/راہیں','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> ٹیمپلیٹ مسئلہ/مسائل','📄 Wrong template'=>'📄 غلط ٹیمپلیٹ','Expected: {expected}'=>'متوقع: {expected}','Current: {current}'=>'موجودہ: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'ٹیمپلیٹ "{expected}" موجود نہیں — پہلے اسے سائٹ ایڈیٹر میں بنائیں۔','Fix Template'=>'ٹیمپلیٹ درست کریں','✅ Template fixed'=>'✅ ٹیمپلیٹ درست ہو گیا','Internal Link Fixer'=>'اندرونی لنک مرمت کرنے والا','Fix All'=>'سب کو درست کریں','Re-scan'=>'دوبارہ اسکین کریں','Language Switcher'=>'زبان سوئچر','Displays the Lingua Forge language switcher.'=>'لینگوا فورج زبان سوئچر دکھاتا ہے۔','Language'=>'زبان','Display'=>'ظاہر کریں','Language label'=>'زبان کا لیبل','Icon only'=>'صرف آئیکن','Icon + label'=>'آئیکن + لیبل','Dropdown direction'=>'ڈراپ ڈاؤن سمت','Down'=>'نیچے','Up'=>'اوپر','You do not have permission to read this post.'=>'آپ کو اس پوسٹ کو پڑھنے کی اجازت نہیں ہے۔','Post not found.'=>'پوسٹ نہیں ملی۔','Limit results to pages in the given Lingua Forge language code.'=>'دی گئی لینگو فورج زبان کوڈ میں صفحات کے نتائج محدود کریں۔','Meta Description'=>'میٹا تفصیل','Using custom meta description.'=>'کاستم میٹا تفصیل استعمال کر رہے ہیں۔','Prefilled from excerpt. Edit to override.'=>'خلاصہ سے پہلے سے بھرا ہوا۔ اوور رائیڈ کرنے کے لیے ترمیم کریں۔','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120–160 حروف کا ہدف۔ خالی چھوڑیں تاکہ خلاصہ کا استعمال ہو۔','↺ Refreshing…'=>'↺ تازہ کاری ہو رہی ہے…','Review translation before applying'=>'درخواست سے پہلے ترجمہ کا جائزہ لیں','Current title'=>'موجودہ عنوان','Translated title'=>'مترجم عنوان','Current content (will be overwritten)'=>'موجودہ مواد (اوور رائٹ کیا جائے گا)','Translated content'=>'مترجم مواد','Footnotes payload (advanced)'=>'حاشیہ نوٹس (ایڈوانسڈ)','Generated meta description'=>'تیار کردہ میٹا تفصیل','Saved to the meta description field when you apply.'=>'جب آپ درخواست دیں گے تو یہ فیلڈ میں محفوظ ہو جائے گا۔','Cancel'=>'منسوخ کریں','Apply translation'=>'ترجمہ لاگو کریں','Generated Content'=>'تیار کردہ مواد','Refine further:'=>'مزید بہتر بنائیں:','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'خاکہ کو بہتر بنانے کے لیے ہدایات شامل کریں — مثلاً اسے مختصر کریں، نتیجہ شامل کریں، زیادہ رسمی انداز استعمال کریں، FAQ بلاک شامل کریں…','↺ Refine'=>'↺ بہتر بنائیں','Copy markup'=>'مارک اپ کاپی کریں','Apply to Editor'=>'ایڈیٹر میں لاگو کریں','Copied ✓'=>'کاپی کیا ✓','Applying…'=>'درخواست دی جا رہی ہے…','Applied ✓'=>'درخواست دی گئی ✓','Refining…'=>'ترقی پذیر…','Refinement failed — please try again.'=>'ترقی میں ناکامی — براہ کرم دوبارہ کوشش کریں۔','Refinement'=>'ترقی','✓ Refined — review the updated draft above.'=>'✓ ترمیم شدہ — اوپر دی گئی مسودہ کا جائزہ لیں۔','Request failed — please try again.'=>'درخواست ناکام — براہ کرم دوبارہ کوشش کریں۔','The editor did not accept the content — please try again.'=>'مدیر نے مواد کو قبول نہیں کیا — براہ کرم دوبارہ کوشش کریں۔','Save the post to persist changes.'=>'تبدیلیاں محفوظ کرنے کے لیے پوسٹ کو محفوظ کریں۔','Apply failed — please try again.'=>'درخواست ناکام — براہ کرم دوبارہ کوشش کریں۔','Copy'=>'نقل کریں','Apply to Meta Description'=>'میٹا تفصیل پر لاگو کریں','Generating…'=>'پیدا ہو رہا ہے…','Generation failed.'=>'پیداوار ناکام۔','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ مواد تیار — جائزہ لینے، بہتر بنانے، اور لاگو کرنے کے لیے اوورلے دیکھیں۔','Request failed.'=>'درخواست ناکام۔','cached'=>'کیش شدہ','Translated to:'=>'ترجمہ شدہ:','tone'=>'لہجہ','Content generated'=>'مواد تیار','Content ready'=>'مواد تیار ہے','footnote(s) translated — applied together with content.'=>'حاشیہ جات ترجمہ شدہ — مواد کے ساتھ مل کر لاگو کیا گیا۔','Chunk translated to:'=>'ٹکڑا ترجمہ ہوا:','Chunk translated'=>'ٹکڑا ترجمہ شدہ','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'نتیجہ کو کاپی کریں اور جہاں ضرورت ہو چپکائیں (مثلاً، براہ راست حاشیہ کے میدان میں)۔','chars'=>'حروف','✓ Good length'=>'✓ اچھا طول','⚠ Borderline'=>'⚠ حد سے زیادہ قریب','✗ Too short'=>'✗ بہت چھوٹا','✗ Too long'=>'✗ بہت لمبا','Target: 140–160 chars for optimal SERP display'=>'ہدف: 140–160 حروف مثالی SERP نمائش کے لیے','SEO character-count info'=>'SEO حروف کی گنتی کی معلومات','↺ Refresh'=>'↺ تازہ کریں','Re-generates and updates the cached result.'=>'کیش شدہ نتیجہ کو دوبارہ پیدا اور اپ ڈیٹ کرتا ہے۔','← Back'=>'← واپس','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'مسودہ بہتر بنانے کے لیے ہدایات شامل کریں — مثلاً، اسے مختصر کریں، نتیجہ کا ایک اختتامی حصہ شامل کریں، زیادہ رسمی انداز استعمال کریں…','Improve writing'=>'تحریر بہتر بنائیں','Make formal'=>'رسمی بنائیں','Make casual'=>'غیر رسمی بنائیں','Make concise'=>'مختصر بنائیں','Expand'=>'وسیع کریں','Bulletize (•-prefixed)'=>'بولٹائز کریں (•-پیش شدہ)','Lead paragraph (≤60 w)'=>'مقدمہ پیراگراف (≤60 الفاظ)','Mark citations needed'=>'حوالہ جات کی ضرورت کو نشان زد کریں','Plain language'=>'سادہ زبان','Translate / Revise'=>'ترجمہ / نظر ثانی','Translate / Revise block'=>'بلاک کا ترجمہ / نظر ثانی','Revision'=>'نظر ثانی','Footnotes'=>'حاشیہ جات','Block Content'=>'بلاک مواد','Revision Type'=>'نظر ثانی کی قسم','Revise'=>'دوبارہ جائزہ لیں','Footnote Content'=>'حاشیہ مواد','Apply to Block'=>'بلاک پر لاگو کریں','Instructions (optional)'=>'ہدایات (اختیاری)','Extra guidance — tone, style, constraints, target audience…'=>'اضافی رہنمائی — لہجہ، انداز، پابندیاں، ہدفی سامعین…','Extra guidance — tone, style, constraints…'=>'اضافی رہنمائی — لہجہ، انداز، پابندیاں…','↑ Detected from current post'=>'↑ موجودہ پوسٹ سے معلوم ہوا','Processing…'=>'پروسیس ہو رہا ہے…','Failed. Please try again.'=>'ناکام۔ براہ کرم دوبارہ کوشش کریں۔','Request failed. Check your connection.'=>'درخواست ناکام۔ اپنی کنکشن چیک کریں۔','Apply to Footnote'=>'حاشیہ پر لاگو کریں','Quick Translate'=>'جلدی ترجمہ','Paste text, or select text in the editor first…'=>'متن چسپاں کریں، یا پہلے ایڈیٹر میں متن منتخب کریں…','Clear input'=>'ان پٹ صاف کریں','Clear'=>'صاف کریں','Instructions / key points'=>'ہدایات / اہم نکات','Describe what to write — topic, key points, structure…'=>'بتائیں کہ کیا لکھنا ہے — موضوع، اہم نکات، ساخت…','Language (optional)'=>'زبان (اختیاری)','— auto-detect —'=>'— خودکار شناخت —','Generate'=>'پیدا کریں','Clear hints'=>'اشارے صاف کریں','Clear All'=>'سب کچھ صاف کریں','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'مزید بہتر بنائیں — مثلاً "اسے مختصر کریں" یا "رسمی انداز استعمال کریں"…','Please enter some text first…'=>'براہ کرم پہلے کچھ متن درج کریں…','Please enter some instructions first…'=>'براہ کرم پہلے کچھ ہدایات درج کریں…','Request failed. Please try again.'=>'درخواست ناکام۔ براہ کرم دوبارہ کوشش کریں۔','Tone:'=>'لہجہ:','Language:'=>'زبان:','Done'=>'ہو گیا','Lingua Forge AI Tools'=>'لینگوا فورج اے آئی ٹولز','Close popover'=>'پاپ اوور بند کریں','Paste text, or select text on the page first…'=>'متن چسپاں کریں، یا پہلے صفحہ پر متن منتخب کریں…','Result will appear here…'=>'نتیجہ یہاں ظاہر ہوگا…','Notice settings'=>'نوٹس سیٹنگز','Notice message'=>'نوٹس پیغام','Shown when no translation exists for the visitor\'s language.'=>'جب کوئی ترجمہ موجود نہ ہو تو ظاہر ہوتا ہے۔','Show home link'=>'ہوم لنک دکھائیں','Adds a link to the home page so visitors can browse in their language.'=>'ایک لنک شامل کرتا ہے تاکہ زائرین اپنی زبان میں براؤز کر سکیں۔','Home link text'=>'ہوم لنک کا متن','block titleMissing Translation Notice'=>'مفقود ترجمہ نوٹس','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'ایک مہذب نوٹس ظاہر کرتا ہے جب موجودہ صفحہ اپنی اصل زبان میں دکھایا جا رہا ہو کیونکہ زائرین کی زبان کے لیے کوئی ترجمہ موجود نہیں ہے۔ یہ Lingua Forge روٹر کے LINGUAFORGE_LANG_FALLBACK_ACTIVE سگنل سے چلتا ہے — جب درخواست کے لوکل کے لیے ترجمہ موجود ہو تو کچھ بھی خارج نہیں ہوتا۔','block keywordlanguage'=>'زبان','block keywordtranslation'=>'ترجمہ','block keywordfallback'=>'واپسی','block keywordi18n'=>'آئی18این','block keywordlinguaforge'=>'لینگوا فورج']];
